DROP TABLE t10; CREATE VIRTUAL TABLE t10 USING fts4(idx,value); INSERT INTO t10 VALUES(1,'one'),(2,'two'),(3,'three'); CREATE TABLE r AS SELECT docId AS d,t10.idx AS i,t10.value AS v FROM t10 JOIN (SELECT 1 AS idx UNION SELECT 2 UNION SELECT 3) AS x WHERE t10 MATCH x.idx AND matchinfo(t10) IS NOT NULL GROUP BY docId ORDER BY 1